=== FILE: rr_arbiter_props.sv ===
// Formal properties for rr_arbiter, written against interface_spec.md.
// Immediate assertions only (open Yosys front end); $past guarded by
// f_past_valid. Single environment assumption: reset in the first cycle.
`default_nettype none
module rr_arbiter_props (
    input wire       clk,
    input wire       rst_n,
    input wire [2:0] req
);
    wire [2:0] grant;
    wire [1:0] last;

    rr_arbiter dut (
        .clk   (clk),
        .rst_n (rst_n),
        .req   (req),
        .grant (grant),
        .last  (last)
    );

    // ------------------------------------------------------------------
    // First-cycle flag and the only assumption: start in reset.
    // ------------------------------------------------------------------
    reg f_past_valid = 1'b0;
    always @(posedge clk)
        f_past_valid <= 1'b1;

    always @(*)
        if (!f_past_valid)
            assume(!rst_n);

    // ------------------------------------------------------------------
    // Reference model of the priority order from spec 2.2:
    // last+1, last+2, last (mod 3).
    // ------------------------------------------------------------------
    reg [1:0] f_p0, f_p1, f_p2;
    always @(*) begin
        case (last)
            2'd0: begin f_p0 = 2'd1; f_p1 = 2'd2; f_p2 = 2'd0; end
            2'd1: begin f_p0 = 2'd2; f_p1 = 2'd0; f_p2 = 2'd1; end
            2'd2: begin f_p0 = 2'd0; f_p1 = 2'd1; f_p2 = 2'd2; end
            default: begin f_p0 = 2'd0; f_p1 = 2'd0; f_p2 = 2'd0; end
        endcase
    end

    reg [2:0] f_exp;
    always @(*) begin
        if (req[f_p0])
            f_exp = 3'b001 << f_p0;
        else if (req[f_p1])
            f_exp = 3'b001 << f_p1;
        else if (req[f_p2])
            f_exp = 3'b001 << f_p2;
        else
            f_exp = 3'b000;
    end

    // ------------------------------------------------------------------
    // Wait counters for RR-BOUND: consecutive edges a requester holds req
    // high without being granted.
    // ------------------------------------------------------------------
    reg [1:0] f_wait0 = 2'd0;
    reg [1:0] f_wait1 = 2'd0;
    reg [1:0] f_wait2 = 2'd0;
    always @(posedge clk) begin
        if (!rst_n || !req[0] || grant[0]) f_wait0 <= 2'd0;
        else                               f_wait0 <= f_wait0 + 2'd1;
        if (!rst_n || !req[1] || grant[1]) f_wait1 <= 2'd0;
        else                               f_wait1 <= f_wait1 + 2'd1;
        if (!rst_n || !req[2] || grant[2]) f_wait2 <= 2'd0;
        else                               f_wait2 <= f_wait2 + 2'd1;
    end

    // ------------------------------------------------------------------
    // Combinational properties (checked every step once out of cycle 0).
    // ------------------------------------------------------------------
    always @(*) begin
        if (f_past_valid) begin
            // Helper / port contract: last is 0, 1 or 2.
            assert(last != 2'd3);

            // At most one grant bit high.
            assert((grant & (grant - 3'b001)) == 3'b000);

            // [req:RR-ONLY-REQUESTERS]
            assert((grant & ~req) == 3'b000);

            // [req:RR-IDLE]
            if (req == 3'b000)
                assert(grant == 3'b000);

            // [req:RR-PICK]
            if (req != 3'b000) begin
                assert(grant == 3'b001 || grant == 3'b010 || grant == 3'b100);
                assert(grant == f_exp);
            end

            // [req:RR-BOUND]: never three ungranted edges in a row.
            assert(f_wait0 != 2'd3);
            assert(f_wait1 != 2'd3);
            assert(f_wait2 != 2'd3);

            // Helper invariants relating wait counters to last (induction).
            if (f_wait0 == 2'd1) assert(last != 2'd0);
            if (f_wait0 == 2'd2) assert(last == 2'd2);
            if (f_wait1 == 2'd1) assert(last != 2'd1);
            if (f_wait1 == 2'd2) assert(last == 2'd0);
            if (f_wait2 == 2'd1) assert(last != 2'd2);
            if (f_wait2 == 2'd2) assert(last == 2'd1);
        end
    end

    // ------------------------------------------------------------------
    // Sequential properties.
    // ------------------------------------------------------------------
    always @(posedge clk) begin
        if (f_past_valid) begin
            // [req:RR-RESET]
            if (!$past(rst_n))
                assert(last == 2'd2);

            if ($past(rst_n)) begin
                // [req:RR-ROTATE]
                if ($past(grant) == 3'b001) assert(last == 2'd0);
                if ($past(grant) == 3'b010) assert(last == 2'd1);
                if ($past(grant) == 3'b100) assert(last == 2'd2);

                // [req:RR-HOLD]
                if ($past(grant) == 3'b000)
                    assert(last == $past(last));

                // [req:RR-YIELD]
                if ($past(grant[0]) && (req[1] || req[2]))
                    assert(!grant[0]);
                if ($past(grant[1]) && (req[0] || req[2]))
                    assert(!grant[1]);
                if ($past(grant[2]) && (req[0] || req[1]))
                    assert(!grant[2]);
            end
        end
    end

    // ------------------------------------------------------------------
    // Covers: scenarios the proof must still allow (vacuity checks).
    // ------------------------------------------------------------------
    always @(posedge clk) begin
        if (f_past_valid) begin
            cover(rst_n && grant == 3'b001);
            cover(rst_n && grant == 3'b010);
            cover(rst_n && grant == 3'b100);
            cover(rst_n && req == 3'b000);
            cover(rst_n && req == 3'b111 && last == 2'd0);
            cover(rst_n && req == 3'b111 && last == 2'd1);
            cover(rst_n && req == 3'b111 && last == 2'd2);
            cover($past(rst_n) && $past(grant) == 3'b000 && $past(last) == 2'd0);
            cover($past(rst_n) && !rst_n && last != 2'd2);
            cover($past(rst_n) && $past(grant[0]) && req == 3'b011 && grant == 3'b010);
            cover(f_wait0 == 2'd2);
            cover(f_wait1 == 2'd2);
            cover(f_wait2 == 2'd2);
        end
    end
endmodule
`default_nettype wire
=== END FILE ===
